#[skip_serializing_none]
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind")]
pub enum IssueWatch {
    #[serde(rename = "history", rename_all = "camelCase")]
    History { session: SessionId, events: Vec<SessionEvent> },
    #[serde(rename = "state", rename_all = "camelCase")]
    State {
        issue: Issue,
        sessions: Vec<Session>,
        session_ids: Vec<SessionId>,
        settled: bool,
        omitted_sessions: i64,
    },
    #[serde(rename = "event", rename_all = "camelCase")]
    Event { session: SessionId, event: SessionEvent },
    #[serde(rename = "gap", rename_all = "camelCase")]
    Gap { session: SessionId, before: Option<i64> },
    #[serde(rename = "missing", rename_all = "camelCase")]
    Missing { issue: IssueId },
}

